data.query:
query Query($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        quantity {
          value unit {code}
        }
        location {
          id
          name
        }
        product {id name}
        productStrategyProcessId
      }
    }
  }
}

query Query($where: AndonRequestWhereInput, $orderBy: [AndonRequestOrderByInput!], $first: Int, $after: String) {
  andonRequest(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        completedAt
        quantity {
          value
          unitId
        }
        destinationLocationId
        shipmentLine {
          id
          quantity {value unitId}
          stagedQuantity {value unitId}
          shipmentLineStageId
        }
        inventory {
          edges {node { 
            id
            inventory {
              id
              quantity {value unitId}
              inventoryStatusId
              inventoryTypeId
              kanbanCardId
              locationId
              lotId
              masterInventoryId
              packagingMaterialId
              productId
              productStrategyProcessId
              receiptLineId
              shipmentLineId
              supplierId
              workOrderId
              workOrderProcessId
            }
          masterInventory {
            id
            inventory {
              edges {node {
                id
                quantity {value unitId}
                inventoryStatusId
                inventoryTypeId
                kanbanCardId
                locationId
                lotId
                masterInventoryId
                packagingMaterialId
                productId
                productStrategyProcessId
                receiptLineId
                shipmentLineId
                supplierId
                workOrderId
                workOrderProcessId
              }} 
            }
          }
          }}
        }
      }
    }
  }
}

data.transform:
(

  $a := andonRequest.edges.node;
  $i := $a.inventory.edges.node;

  {

    "iu": $i.inventory.{
      "update": {
        "inventoryStatusId": "Staged",
        "shipmentLineId": $a.shipmentLine.id
      }, "where": {
        "id": id
      }
    },
    "ai": $i.{
      "update": {
        "loaded": false,
        "complete":true
      },
      "where": {
        "id":id
      }
    },
    "it": $i.inventory.{
      "create": {
        "sourceQuantity": quantity,
        "customData": $state.claims,
        "destinationQuantity": quantity,
        "sourceInventoryId":id,
        "destinationInventoryId":id,
        "sourceLocationId": locationId,
        "destinationLocationId": $a.destinationLocationId,
        "sourceInventoryStatusId": inventoryStatusId,
        "destinationInventoryStatusId": "Staged",
        "sourceLotId": lotId,
        "destinationLotId": lotId,
        "sourceProductId":productId,
        "destinationProductId":productId,
        "sourceProductStrategyProcessId":productStrategyProcessId,
        "destinationProductStrategyProcessId":productStrategyProcessId,
        "sourceWorkOrderProcessId": workOrderProcessId,
        "destinationWorkOrderProcessId": workOrderProcessId,
        "sourceMasterInventoryId":masterInventoryId,
        "destinationMasterInventoryId":masterInventoryId,
        "statusId": "Informational",
        "transactionTypeId": "Shipment Stage"
      }
    },
    "su": $a.shipmentLine.{
      "update": {
        "stagedQuantity": stagedQuantity.{
          "value": value + $sum($i.inventory.quantity.value),
          "unitId": unitId
        },
        "shipmentLineStageId": "Staged"
      }, 
      "where": {
        "id": id
      }
    }

  }
)

