                  value
                  unitId
                }
              }
            }
          }
        }
        shipFromFacilityId
        shipToFacilityId

      }
    }
  }
}

query Query($where: SalesOrderWhereInput, $whereLines: SalesOrderLineWhereInput, $whereReleaseLines: SalesOrderLineReleaseWhereInput) {
  salesOrder(where: $where, first: 10) {
    edges {
      node {
        id
        number
        facilityId
        sCustomerAddressId
        bCustomerAddressId
        lines(where: $whereLines) {
          edges {
            node {
              id
              sCustomerAddressId
              bCustomerAddressId
              productStrategy {
                saleUnitId
                unitType {
                  id
                }
              }
              quantity {
                value
                unitId
              }
              productId
              salesOrderLineReleases(where: $whereReleaseLines) {
                edges {
                  node {
                    id
                    number
                    balanceQuantity
                    quantity
                    scheduledQuantity
                    shippedQuantity
                    releaseNo
                    dueAt
                    expectedShipAt
                    shipAt
                    salesOrderLineReleaseStatus {
                      id
                      name
                      active
                      cancelled
                      closed
                      default
                      hold
                      open
                      partialShipped
                      productionHold
                      shipmentHold
                      shipped
                      system
                      usable
                      color
                      message
                      customData
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
